/* VOTE/TRACK: only observed snapshots, never interpolated historical votes. */
(() => {
  'use strict';
  const $ = id => document.getElementById(id);
  const nf = new Intl.NumberFormat('ko-KR');
  const palette = ['#c2ee64', '#b3a2ff', '#76cef0', '#f1b87a', '#ed9cca', '#8cd5b1'];
  const colors = {rescene:palette[0],riize:palette[1],'shownu x hyungwon':palette[2]};
  const gapDefs = [{id:'gap12',name:'1–2위',a:0,b:1,color:palette[0]}, {id:'gap23',name:'2–3위',a:1,b:2,color:palette[1]}, {id:'gap13',name:'1–3위',a:0,b:2,color:palette[2]}];
  const state = {data:window.KGMA_SEED,metric:'votes',range:'all',historyLimit:12,fetching:false,loadFailed:false};
  const escapeHTML = value => String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const fmt = n => nf.format(n);
  const share = (team,snap) => 100*team.votes/snap.totalVotes;
  const displayShare = (team,snap) => Number.isFinite(team.reportedShare)?team.reportedShare.toFixed(1):share(team,snap).toFixed(1);
  const normalizedId = team => String(team.id||team.name).normalize('NFKC').trim().toLowerCase().replace(/\s+/g,' ');
  function colorOf(team){const id=normalizedId(team);if(colors[id])return colors[id];let h=0;for(const c of id)h=(h*31+c.charCodeAt(0))>>>0;return palette[3+h%3];}
  function kst(iso,mode='full') {const d=new Date(iso);const p=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(d);const f=Object.fromEntries(p.map(x=>[x.type,x.value]));return mode==='time'?`${f.hour}:${f.minute}`:mode==='short'?`${f.month}.${f.day} ${f.hour}:${f.minute}`:`${f.year}.${f.month}.${f.day} ${f.hour}:${f.minute}`;}
  function normalize(data) {
    if(!data || data.schemaVersion!==1 || !Array.isArray(data.snapshots) || !data.snapshots.length)throw new Error('기록 형식이 올바르지 않습니다.');
    const seen=new Set();
    const snapshots=data.snapshots.map(s=>{
      if(!Number.isFinite(Date.parse(s.sourceAt))||seen.has(s.sourceAt)||!Number.isSafeInteger(s.totalVotes)||s.totalVotes<=0||!Array.isArray(s.top3)||s.top3.length!==3)throw new Error('유효하지 않은 집계 기록입니다.');
      seen.add(s.sourceAt);let sum=0;const ids=new Set();
      const top3=s.top3.map((t,i)=>{
        if(!t.name||!Number.isSafeInteger(t.votes)||t.votes<0||t.votes>s.totalVotes)throw new Error('득표수 형식이 올바르지 않습니다.');
        const id=normalizedId(t);if(ids.has(id))throw new Error('중복된 아티스트입니다.');ids.add(id);sum+=t.votes;
        if(i&&s.top3[i-1].votes<t.votes)throw new Error('순위와 표수가 일치하지 않습니다.');
        if(t.reportedShare!=null&&(!Number.isFinite(t.reportedShare)||Math.abs(t.reportedShare-100*t.votes/s.totalVotes)>.151))throw new Error('점유율과 표수가 일치하지 않습니다.');
        return {...t,id,rank:i+1};
      });if(sum>s.totalVotes)throw new Error('총투표수보다 상위 득표수의 합이 큽니다.');
      return {...s,top3};
    }).sort((a,b)=>Date.parse(a.sourceAt)-Date.parse(b.sourceAt));
    return {...data,snapshots};
  }
  const latest = () => state.data.snapshots.at(-1);
  function previousFive(){const all=state.data.snapshots;const last=Date.parse(latest().sourceAt);return all.find(s=>last-Date.parse(s.sourceAt)===300000)||null;}
  function getSeries() {return state.metric==='gap'?gapDefs:latest().top3.map(t=>({id:t.id,name:t.name,color:colorOf(t)}));}
  function getValue(s,series) {if(state.metric==='gap')return s.top3[series.a].votes-s.top3[series.b].votes;const team=s.top3.find(t=>t.id===series.id);return team?(state.metric==='share'?share(team,s):team.votes):null;}
  function windowSnapshots(){const all=state.data.snapshots;if(state.range==='all')return all;const min=Date.parse(latest().sourceAt)-Number(state.range)*3600000;return all.filter(s=>Date.parse(s.sourceAt)>=min);}
  function change(v,digits=0){return `${v>0?'+':v<0?'−':''}${digits?Math.abs(v).toFixed(digits):fmt(Math.abs(v))}`;}
  function status(){const last=latest();const capture=last.origin==='user_capture';const stale=Date.now()-Date.parse(last.sourceAt)>15*60000;const failed=state.data.collector?.state==='error';const stopped=state.data.collector?.state==='stopped';$('status-pill').className='status-pill '+(capture?'':stale||failed||stopped?'stale':'live');$('status-label').textContent=capture?'캡처 기록':failed?'수집 오류':stopped?'수집 종료':stale?'갱신 지연':'최근 수집 확인';$('source-time').textContent=kst(last.sourceAt);let note=capture?'첨부 화면의 실제 수치 1건입니다. 자동 수집 연결 전이며, 기록이 더 쌓이면 추이선이 표시됩니다.':failed?'최근 수집에 실패했습니다. 마지막으로 확인한 기록을 표시하며, 누락된 값은 채우지 않습니다.':stopped?'설정된 수집 기간이 끝났습니다. 마지막으로 저장된 기록을 표시합니다.':stale?'새 기록이 15분 이상 들어오지 않았습니다. 아래 집계 시각의 수치를 표시합니다.':'최근 수집된 기록을 표시합니다. 5분 간격 수집을 요청하며, 예약 실행과 공개 반영에는 지연이 생길 수 있습니다.';if(state.loadFailed)note+=' 최신 기록 파일을 불러오지 못해 보관된 기록을 표시합니다.';$('notice-text').textContent=note;$('notice').className='notice '+(!capture&&!stale&&!failed?'good':'');}
  function renderCards(){const last=latest();$('leaders').innerHTML=last.top3.map((t,i)=>`<article class="leader ${i===0?'first':''}" style="--color:${colorOf(t)}"><div class="leader-top"><span class="rank-badge"><b>${String(i+1).padStart(2,'0')}</b> RANK</span>${i===0?'<span class="mini-label">현재 선두</span>':''}</div><h2 class="artist" title="${escapeHTML(t.name)}"><i class="artist-dot"></i>${escapeHTML(t.name)}</h2><div class="count-row"><strong class="vote-value">${fmt(t.votes)}</strong><span class="unit">표</span><span class="share-value">${displayShare(t,last)}<span>%</span></span></div><div class="leader-bottom"><span>전체 투표 중 점유율</span><b>${i===0?`2위와 ${fmt(t.votes-last.top3[1].votes)}표 차이`:`1위와 ${fmt(last.top3[0].votes-t.votes)}표 차이`}</b></div></article>`).join('');$('total-votes').textContent=fmt(last.totalVotes);$('sample-count').textContent=fmt(state.data.snapshots.length);const sum=last.top3.reduce((s,t)=>s+t.votes,0);$('top-share').textContent=(sum/last.totalVotes*100).toFixed(1)+'%';$('other-share').textContent=((last.totalVotes-sum)/last.totalVotes*100).toFixed(1)+'%';$('share-track').innerHTML=last.top3.map(t=>`<i style="width:${share(t,last)}%;background:${colorOf(t)}" title="${escapeHTML(t.name)} ${displayShare(t,last)}%"></i>`).join('')+`<i style="width:${100-sum/last.totalVotes*100}%;background:#3b4332" title="그 외"></i>`;}
  function renderGaps(){const last=latest(),max=last.top3[0].votes-last.top3[2].votes;$('gap-list').innerHTML=gapDefs.map(g=>{const n=last.top3[g.a].votes-last.top3[g.b].votes;return `<div class="gap-row"><span class="gap-ranks"><b>${g.a+1}</b>위 <span>–</span> <b>${g.b+1}</b>위</span><div><span class="pair-names">${escapeHTML(last.top3[g.a].name)} · ${escapeHTML(last.top3[g.b].name)}</span><div class="gap-track"><i style="width:${max?n/max*100:0}%;background:${g.color}"></i></div></div><strong class="gap-value">${fmt(n)}<small>표</small></strong></div>`;}).join('');}
  function renderPace(){const last=latest(),prev=previousFive();$('pace-tag').textContent=prev?'5분 비교':'기록 대기';$('pace-body').innerHTML=last.top3.map(t=>{const p=prev?.top3.find(x=>x.id===t.id);const delta=p?t.votes-p.votes:null,pp=p?share(t,last)-share(p,prev):null;return `<tr><td><span class="table-artist" style="--color:${colorOf(t)}"><i></i>${escapeHTML(t.name)}</span></td><td class="${delta==null?'no-value':delta>=0?'positive':'negative'}">${delta==null?'—':change(delta)+'표'}</td><td class="${pp==null?'no-value':pp>=0?'positive':'negative'}">${pp==null?'—':change(pp,2)+'%p'}</td></tr>`;}).join('');$('pace-note').textContent=prev?`${kst(prev.sourceAt,'short')} → ${kst(last.sourceAt,'time')} · 이전 시점에 상위 3위 밖인 팀은 비교 값이 없습니다.`:'정확히 5분 전의 기록이 있어야 증가량을 계산합니다. 아직 없는 값은 —로 표시합니다.';}
  function renderHistory(){const all=[...state.data.snapshots].reverse();$('history-body').innerHTML=all.slice(0,state.historyLimit).map(s=>`<tr><td>${kst(s.sourceAt,'short')}${s.origin==='user_capture'?' · 캡처':''}</td>${s.top3.map(t=>`<td><span class="history-name">${escapeHTML(t.name)}</span>${fmt(t.votes)}<span class="history-name" style="display:inline;margin-left:7px">${displayShare(t,s)}%</span></td>`).join('')}<td>${fmt(s.top3[0].votes-s.top3[1].votes)}표</td></tr>`).join('');$('load-more').hidden=all.length<=state.historyLimit;}
  function graphGeometry(){const rows=windowSnapshots(),series=getSeries();const mobile=matchMedia('(max-width:760px)').matches;const W=mobile?600:1100,H=mobile?360:310;const box={x:60,y:20,w:W-88,h:H-69};const times=rows.map(s=>Date.parse(s.sourceAt));let xmin=times[0],xmax=times.at(-1);if(xmin===xmax){xmin-=300000;xmax+=300000;}const values=rows.flatMap(s=>series.map(line=>getValue(s,line))).filter(Number.isFinite);let max=Math.max(1,...values)*1.12;if(state.metric==='share')max=Math.min(100,max);const step=Math.pow(10,Math.floor(Math.log10(max/4)));const raw=max/4/step;const nice=(raw<=1?1:raw<=2?2:raw<=2.5?2.5:raw<=5?5:10)*step;max=Math.ceil(max/nice)*nice;return {rows,series,W,H,box,xmin,xmax,ymax:max,x:t=>box.x+(t-xmin)/(xmax-xmin)*box.w,y:v=>box.y+box.h-v/max*box.h};}
  function renderChart(){const g=graphGeometry(),{rows,series,W,H,box,x,y,xmin,xmax,ymax}=g;const svg=$('trend-chart');svg.setAttribute('viewBox',`0 0 ${W} ${H}`);const unit=state.metric==='share'?'%':'표';$('chart-unit').textContent=state.metric==='votes'?'득표수 (표)':state.metric==='share'?'전체 대비 점유율 (%)':'순위 간 표차 (표)';$('chart-legend').innerHTML=series.map(s=>`<span class="legend-item" style="--color:${s.color}"><i></i>${escapeHTML(s.name)}</span>`).join('');const grid=[];for(let i=0;i<=4;i++){const v=ymax*i/4,yy=y(v);grid.push(`<line x1="${box.x}" y1="${yy}" x2="${box.x+box.w}" y2="${yy}" stroke="#343c2c" stroke-dasharray="${i?'3 5':'0'}" stroke-width="1"/><text x="${box.x-12}" y="${yy+4}" text-anchor="end" fill="#9ba58c" font-size="11">${state.metric==='share'?Number(v.toFixed(1))+'%':fmt(Math.round(v))}</text>`);}const labels=rows.length===1?[Date.parse(rows[0].sourceAt)]:Array.from({length:W<700?3:6},(_,i)=>xmin+(xmax-xmin)*i/(W<700?2:5));labels.forEach(t=>grid.push(`<text x="${x(t)}" y="${box.y+box.h+27}" text-anchor="middle" fill="#9ba58c" font-size="11">${kst(new Date(t).toISOString(),xmax-xmin>86400000?'short':'time')}</text>`));let paths='';for(const s of series){let path='',active=false,lastTime=null;for(const r of rows){const v=getValue(r,s),time=Date.parse(r.sourceAt);if(v==null){active=false;continue;}if(lastTime!==null&&time-lastTime>390000)active=false;path+=`${active?'L':'M'}${x(time).toFixed(2)},${y(v).toFixed(2)} `;active=true;lastTime=time;}paths+=`<path d="${path}" fill="none" stroke="${s.color}" stroke-width="2.5" stroke-linejoin="round" stroke-linecap="round"/>`;for(let i=0;i<rows.length;i++){const r=rows[i],v=getValue(r,s);if(v==null)continue;if(rows.length>100&&i!==rows.length-1)continue;paths+=`<circle cx="${x(Date.parse(r.sourceAt))}" cy="${y(v)}" r="${rows.length===1?5:3}" fill="${s.color}" stroke="#191c17" stroke-width="2"><title>${escapeHTML(s.name)} · ${kst(r.sourceAt)} · ${state.metric==='share'?v.toFixed(2):fmt(v)}${unit}</title></circle>`;}}
    if(rows.length===1){grid.push(`<line x1="${x(Date.parse(rows[0].sourceAt))}" x2="${x(Date.parse(rows[0].sourceAt))}" y1="${box.y}" y2="${box.y+box.h}" stroke="#6c785a" stroke-dasharray="3 6"/><text x="${box.x+box.w-4}" y="${box.y+14}" text-anchor="end" fill="#9da98c" font-size="11">첫 기록 · 다음 집계를 기다리고 있어요</text>`);}
    const hits=rows.map((r,i)=>`<rect x="${x(Date.parse(r.sourceAt))-Math.max(3,Math.min(24,box.w/rows.length/2))}" y="${box.y}" width="${Math.max(6,Math.min(48,box.w/rows.length))}" height="${box.h}" fill="transparent" data-point="${i}" tabindex="0" aria-label="${escapeHTML(kst(r.sourceAt)+' 집계 기록')}"/>`).join('');svg.innerHTML=`<title>${escapeHTML($('chart-unit').textContent)} 추이</title><desc>관측된 ${rows.length}개 기록. 없는 과거 데이터와 5분보다 긴 누락 구간을 임의로 채우지 않습니다.</desc>${grid.join('')}${paths}${hits}`;svg.setAttribute('aria-label',`${$('chart-unit').textContent} 추이, ${rows.length}개 기록`);svg.querySelectorAll('[data-point]').forEach(el=>{const show=()=>showTooltip(rows[Number(el.dataset.point)],series,el,g);el.addEventListener('pointerenter',show);el.addEventListener('focus',show);el.addEventListener('pointerleave',hideTooltip);el.addEventListener('blur',hideTooltip);});$('chart-note').textContent=rows.length===1?'실제 기록 1건 · 추이선은 두 번째 기록부터 표시됩니다.':state.metric==='gap'?'각 시점의 순위 간 표차 · 수집이 빠진 구간은 선을 잇지 않습니다.':'현재 상위 3팀을 팀별로 추적 · 미관측 구간은 선을 잇지 않습니다.';$('chart-window').textContent=`${kst(rows[0].sourceAt,'short')} — ${kst(rows.at(-1).sourceAt,'short')}`;
  }
  function showTooltip(s,series,el,g){const tt=$('tooltip');tt.innerHTML=`<strong>${kst(s.sourceAt)} KST</strong>`+series.map(line=>{const v=getValue(s,line);return `<p><span><i style="background:${line.color}"></i>${escapeHTML(line.name)}</span><b>${v==null?'—':state.metric==='share'?v.toFixed(2)+'%':fmt(v)+'표'}</b></p>`;}).join('');tt.hidden=false;const wrap=$('trend-chart').getBoundingClientRect();const p=g.x(Date.parse(s.sourceAt))/g.W*wrap.width;tt.style.left=Math.max(0,Math.min(wrap.width-tt.offsetWidth,p+12))+'px';tt.style.top='38px';}
  function hideTooltip(){$('tooltip').hidden=true;}
  function render(){status();renderCards();renderGaps();renderPace();renderHistory();renderChart();}
  async function refresh(manual=false){if(state.fetching)return;state.fetching=true;$('refresh-button').disabled=true;try{const url=new URL('./data/history.json',location.href);url.searchParams.set('v',Math.floor(Date.now()/60000));const response=await fetch(url,{cache:'no-store'});if(!response.ok)throw new Error('기록을 읽지 못했습니다.');const next=normalize(await response.json());if(Date.parse(next.snapshots.at(-1).sourceAt)<Date.parse(latest().sourceAt))throw new Error('더 오래된 기록입니다.');state.data=next;state.loadFailed=false;render();if(manual)toast('저장된 최신 기록을 불러왔습니다.');}catch(e){state.loadFailed=true;status();if(manual)toast('새 기록을 불러오지 못했습니다. 기존 기록을 유지합니다.');}finally{state.fetching=false;$('refresh-button').disabled=false;}}
  function toast(text){$('toast').textContent=text;$('toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').hidden=true,4200);}
  function download(blob,name){const u=URL.createObjectURL(blob);const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),10000);}
  function exportCSV(){const cells=v=>{let s=String(v??'');if(/^[=+@\-]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};const rows=[['집계시각_KST','출처','전체투표','순위','아티스트','득표수','전체대비점유율_%','표시점유율_%','1_2위표차','2_3위표차','1_3위표차']];for(const s of state.data.snapshots)for(const t of s.top3)rows.push([kst(s.sourceAt),s.origin,s.totalVotes,t.rank,t.name,t.votes,share(t,s).toFixed(4),displayShare(t,s),s.top3[0].votes-s.top3[1].votes,s.top3[1].votes-s.top3[2].votes,s.top3[0].votes-s.top3[2].votes]);download(new Blob(['\uFEFF'+rows.map(r=>r.map(cells).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),'kgma-top3-history.csv');}
  async function copySummary(){const s=latest();const lines=[`[2026 KGMA] ${kst(s.sourceAt)} KST 기준`,...s.top3.map(t=>`${t.rank}위 ${t.name}: ${fmt(t.votes)}표 (${displayShare(t,s)}%)`),...gapDefs.map(g=>`${g.name} 표차: ${fmt(s.top3[g.a].votes-s.top3[g.b].votes)}표`),`총투표수 ${fmt(s.totalVotes)}표`,s.origin==='user_capture'?'첨부 화면에서 확인한 기록 · 실시간 연결 전':'Berriz 공개 투표 집계',location.protocol==='file:'?'https://berriz.in/ko/vote/2026kgma/':location.href];try{await navigator.clipboard.writeText(lines.join('\n'));toast('집계 요약을 복사했습니다.');}catch{toast('복사 권한이 없습니다. CSV 다운로드를 이용해 주세요.');}}
  async function exportPNG(){const btn=$('png-button');btn.disabled=true;try{await document.fonts.ready;const s=latest(),g=graphGeometry();const canvas=document.createElement('canvas');canvas.width=2400;canvas.height=1560;const c=canvas.getContext('2d');c.scale(2,2);c.fillStyle='#10120f';c.fillRect(0,0,1200,780);const text=(str,x,y,size=15,color='#edf0e8',weight=400)=>{c.fillStyle=color;c.font=`${weight} ${size}px "DM Sans", "Noto Sans KR", sans-serif`;c.fillText(str,x,y);};text('VOTE/TRACK',50,55,22,'#c2ee64',700);text('2026 KGMA · TOP 3',50,99,29,'#edf0e8',700);text(kst(s.sourceAt)+' KST 기준',850,94,16,'#b7c3a6');s.top3.forEach((t,i)=>{const x=50+i*373;c.fillStyle='#1b2116';c.fillRect(x,133,354,155);text(String(i+1).padStart(2,'0')+'  '+t.name,x+18,162,t.name.length>18?13:17,colorOf(t),600);text(fmt(t.votes),x+18,220,43,'#edf0e8',600);text(displayShare(t,s)+'%',x+255,218,25,colorOf(t));text(i===0?'2위와 '+fmt(t.votes-s.top3[1].votes)+'표 차이':'1위와 '+fmt(s.top3[0].votes-t.votes)+'표 차이',x+18,263,13,'#aebb9d');});text($('chart-unit').textContent+' · '+$('chart-window').textContent,50,329,16,'#c7d1bb',500);
      const xx=t=>100+(t-g.xmin)/(g.xmax-g.xmin)*1025,yy=v=>665-v/g.ymax*295;for(let i=0;i<=4;i++){const v=g.ymax*i/4;c.strokeStyle='#35402b';c.lineWidth=1;c.beginPath();c.moveTo(100,yy(v));c.lineTo(1125,yy(v));c.stroke();text(state.metric==='share'?Number(v.toFixed(1))+'%':fmt(Math.round(v)),44,yy(v)+4,11,'#a0ad92');}
      for(const [j,line]of g.series.entries()){text('● '+line.name,50+j*350,355,12,line.color);c.strokeStyle=line.color;c.lineWidth=2.6;c.beginPath();let active=false,lastT=null;for(const r of g.rows){const v=getValue(r,line),t=Date.parse(r.sourceAt);if(v==null){active=false;continue;}if(lastT!==null&&t-lastT>390000)active=false;if(active)c.lineTo(xx(t),yy(v));else c.moveTo(xx(t),yy(v));active=true;lastT=t;}c.stroke();for(const r of g.rows){const v=getValue(r,line);if(v==null)continue;c.beginPath();c.fillStyle=line.color;c.arc(xx(Date.parse(r.sourceAt)),yy(v),3.2,0,Math.PI*2);c.fill();}}
      text(kst(g.rows[0].sourceAt,'short'),90,692,12,'#a0ad92');if(g.rows.length>1)text(kst(g.rows.at(-1).sourceAt,'short'),1020,692,12,'#a0ad92');text(g.rows.length===1?'실제 기록 1건 · 두 번째 기록부터 추이선이 표시됩니다.':$('chart-note').textContent,50,729,13,'#a0ad92');text('데이터 출처 Berriz · 비공식 팬 대시보드 · 전체 투표 대비 점유율',50,754,11,'#829272');canvas.toBlob(blob=>{if(blob)download(blob,`kgma-top3-${state.metric}.png`);else toast('이미지 생성에 실패했습니다.');},'image/png');}catch{toast('이미지 생성에 실패했습니다.');}finally{btn.disabled=false;}}
  document.querySelectorAll('[data-metric]').forEach(button=>button.addEventListener('click',()=>{state.metric=button.dataset.metric;document.querySelectorAll('[data-metric]').forEach(b=>{b.classList.toggle('selected',b===button);b.setAttribute('aria-pressed',String(b===button));});hideTooltip();renderChart();}));
  document.querySelectorAll('[data-range]').forEach(button=>button.addEventListener('click',()=>{state.range=button.dataset.range;document.querySelectorAll('[data-range]').forEach(b=>{b.classList.toggle('selected',b===button);b.setAttribute('aria-pressed',String(b===button));});hideTooltip();renderChart();}));
  $('refresh-button').addEventListener('click',()=>refresh(true));$('csv-button').addEventListener('click',exportCSV);$('copy-button').addEventListener('click',copySummary);$('png-button').addEventListener('click',exportPNG);$('load-more').addEventListener('click',()=>{state.historyLimit+=24;renderHistory();});let resizeTimer;addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(renderChart,120);});document.addEventListener('visibilitychange',()=>{if(!document.hidden)refresh();});
  state.data=normalize(state.data);render();if(location.protocol!=='file:')refresh();setInterval(()=>{if(!document.hidden)refresh();},300000);
})();
